package edu.ankara.audiometer.domain.algorithm;
import edu.ankara.audiometer.domain.config.HughsonWestlakeConfig;import edu.ankara.audiometer.domain.model.*;import java.util.*;import java.util.stream.*;
public final class ThresholdDetector { private ThresholdDetector(){}
 public static ThresholdDecision detectThreshold(List<TonePresentation> presentations, HughsonWestlakeConfig config){ if(presentations.isEmpty()) return ThresholdDecision.notReached(config.criterion(),"No presentations"); var last=presentations.getLast(); var relevant=presentations.stream().filter(p->p.ear()==last.ear()&&p.frequency().equals(last.frequency())&&p.validAscendingTrial()).toList(); return relevant.stream().map(TonePresentation::intensity).distinct().sorted().map(i->decisionForIntensity(i,relevant,config)).filter(ThresholdDecision::reached).findFirst().orElse(ThresholdDecision.notReached(config.criterion(),"Criterion not yet satisfied")); }
 private static ThresholdDecision decisionForIntensity(IntensityDbHL i,List<TonePresentation> rel,HughsonWestlakeConfig c){ var trials=rel.stream().filter(p->p.intensity().equals(i)&&p.response().isPresent()).toList(); int heard=(int)trials.stream().filter(p->p.response().orElseThrow().heard()).count(); if(trials.size()>=c.criterion().window && heard>=c.criterion().required) return ThresholdDecision.reached(i,c.criterion(),heard+"/"+trials.size()+" ascending responses at "+i.value()+" dB HL"); return ThresholdDecision.notReached(c.criterion(),"not enough at "+i.value()); }
 public static boolean isThresholdReached(List<TonePresentation> presentations,HughsonWestlakeConfig config){return detectThreshold(presentations,config).reached();}
}
